// One signal pulled out as an example of consuming a single value.
//
// cells_v is rounded for display; cells_100uv carries the raw device value
// in the 100 uV steps the LTC681x family uses, so read that when the number
// is going to be stored or used in arithmetic.
const cells = msg.payload.cells_100uv || [];

if (cells.length === 0) {
    return null;   // nothing reported yet
}

msg.topic = "multibus/cell1";
msg.payload = {
    volts: cells[0] / 10000,
    raw_100uv: cells[0],
    age_ms: msg.payload.age_ms,
    simulated: msg.payload.simulated === true
};

// Show the value on the node itself, so the flow is readable at a glance.
node.status({ fill: "green", shape: "dot",
              text: msg.payload.volts.toFixed(4) + " V" });

return msg;
